from pathlib import Path
import json, urllib.request, urllib.error, time, re
base=Path('/work/targetmol/run/agent/project/experiments/target_analysis')
hits=json.loads((base/'rcsb_sequence_hits.json').read_text())

def fetch_json(url):
    req=urllib.request.Request(url, headers={'User-Agent':'targetmol-bounded-agent'})
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.loads(resp.read())

def compact_entry(pdb_id, entity_id):
    entry=fetch_json(f'https://data.rcsb.org/rest/v1/core/entry/{pdb_id}')
    ids=entry.get('rcsb_entry_container_identifiers',{})
    poly=None
    try:
        poly=fetch_json(f'https://data.rcsb.org/rest/v1/core/polymer_entity/{pdb_id}/{entity_id}')
    except Exception as e:
        poly={'error':str(e)[:120]}
    nonpolys=[]
    for npid in ids.get('non_polymer_entity_ids') or []:
        try:
            np=fetch_json(f'https://data.rcsb.org/rest/v1/core/nonpolymer_entity/{pdb_id}/{npid}')
            compid=(np.get('pdbx_entity_nonpoly') or {}).get('comp_id') or (np.get('rcsb_nonpolymer_entity_container_identifiers') or {}).get('nonpolymer_comp_id')
            name=(np.get('pdbx_entity_nonpoly') or {}).get('name')
            chem=np.get('rcsb_nonpolymer_entity',{})
            desc=chem.get('pdbx_description') or name
            nonpolys.append({'entity_id':npid,'comp_id':compid,'name':desc})
        except Exception as e:
            nonpolys.append({'entity_id':npid,'error':str(e)[:120]})
    exp=entry.get('exptl') or []
    method=exp[0].get('method') if exp else None
    refine=entry.get('refine') or []
    res=refine[0].get('ls_d_res_high') if refine else None
    struct=entry.get('struct') or {}
    title=struct.get('title')
    info=entry.get('rcsb_entry_info') or {}
    keywords=entry.get('struct_keywords') or {}
    poly_entity=poly or {}
    desc=(poly_entity.get('rcsb_polymer_entity') or {}).get('pdbx_description')
    srcs=[]
    for src in (poly_entity.get('rcsb_entity_source_organism') or []):
        srcs.append(src.get('scientific_name') or src.get('ncbi_scientific_name'))
    uniprots=[]
    for ref in (poly_entity.get('rcsb_polymer_entity_container_identifiers') or {}).get('reference_sequence_identifiers') or []:
        if ref.get('database_name')=='UniProt': uniprots.append(ref.get('database_accession'))
    ec=[]
    for enz in (poly_entity.get('rcsb_polymer_entity') or {}).get('rcsb_ec_lineage') or []:
        if enz.get('id'): ec.append(enz.get('id'))
    return {'pdb_id':pdb_id,'entity_id':entity_id,'title':title,'method':method,'resolution_A':res,'classification':keywords.get('pdbx_keywords'),'entity_description':desc,'organism':sorted(set(filter(None,srcs))),'uniprot':sorted(set(filter(None,uniprots))),'ec':sorted(set(ec)),'nonpolymer_ligands':nonpolys,'polymer_entity_count':info.get('polymer_entity_count'),'nonpolymer_entity_count':info.get('nonpolymer_entity_count')}

summary=[]
for target in hits:
    t={'target':target['target'],'seq_len':target['seq_len'],'top_structures':[]}
    seen=set()
    for h in target.get('top_hits',[])[:8]:
        ident=h['identifier']
        m=re.match(r'([0-9A-Za-z]{4})_(\\d+)', ident)
        if not m: continue
        pdb_id=m.group(1).upper(); entity_id=m.group(2)
        if pdb_id in seen: continue
        seen.add(pdb_id)
        try:
            ce=compact_entry(pdb_id,entity_id)
            ce['seq_search_score']=h.get('score')
            t['top_structures'].append(ce)
            print(target['target'], pdb_id, ce.get('entity_description'), 'ligands', [(l.get('comp_id'), l.get('name')) for l in ce.get('nonpolymer_ligands',[])[:6]])
        except Exception as e:
            t['top_structures'].append({'pdb_id':pdb_id,'entity_id':entity_id,'error':type(e).__name__+': '+str(e)[:160]})
            print(target['target'], pdb_id, 'ERROR', type(e).__name__, str(e)[:120])
        time.sleep(0.2)
    summary.append(t)
(base/'rcsb_public_compact_summary.json').write_text(json.dumps(summary,indent=2,sort_keys=True), encoding='utf-8')
